const requester = $input.first().json;
const { contacts } = $('Validate Session ken & Rows').first().json;

if (!requester.id || !requester.active) {
  throw new Error('Invalid session.');
}

const queryParams = [];
let paramIndex = 1;

// companies.name is UNIQUE — upsert distinct company names first, then
// link each contact to its company via account_id (contacts has no
// company_name column; company is a separate normalized table).
const companyNames = [...new Set(
  contacts.map((c) => (c.company_name || '').trim()).filter((n) => n)
)];

const companyValuesSql = companyNames.map((name) => {
  const sql = `($${paramIndex}::varchar, $${paramIndex + 1}::integer, NOW(), NOW())`;
  queryParams.push(name, requester.id);
  paramIndex += 2;
  return sql;
});

const contactValuesSql = contacts.map((c) => {
  const companyName = (c.company_name || '').trim() || null;
  const sql = `($${paramIndex}::varchar, $${paramIndex+1}::varchar, $${paramIndex+2}::varchar, $${paramIndex+3}::varchar, $${paramIndex+4}::varchar, $${paramIndex+5}::varchar, $${paramIndex+6}::varchar, $${paramIndex+7}::varchar, $${paramIndex+8}::integer)`;
  queryParams.push(
    c.first_name, c.last_name, c.email, c.phone,
    c.city, c.country, c.lead_status, companyName, requester.id
  );
  paramIndex += 9;
  return sql;
});

const contactsCte = `new_contacts (first_name, last_name, email, phone, city, country, lead_status, company_name, owner_id) AS (
  VALUES ${contactValuesSql.join(', ')}
)`;

const sqlQuery = companyNames.length
  ? `
    WITH upserted_companies AS (
      INSERT INTO companies (name, owner_id, created_at, updated_at)
      VALUES ${companyValuesSql.join(', ')}
      ON CONFLICT (name) DO UPDATE SET name = EXCLUDED.name
      RETURNING id, name
    ),
    ${contactsCte}
    INSERT INTO contacts (first_name, last_name, email, phone, city, country, lead_status, account_id, owner_id, created_at, updated_at)
    SELECT nc.first_name, nc.last_name, nc.email, nc.phone, nc.city, nc.country, nc.lead_status, uc.id, nc.owner_id, NOW(), NOW()
    FROM new_contacts nc
    LEFT JOIN upserted_companies uc ON uc.name = nc.company_name
    RETURNING id;
  `
  : `
    WITH ${contactsCte}
    INSERT INTO contacts (first_name, last_name, email, phone, city, country, lead_status, account_id, owner_id, created_at, updated_at)
    SELECT first_name, last_name, email, phone, city, country, lead_status, NULL::integer, owner_id, NOW(), NOW()
    FROM new_contacts
    RETURNING id;
  `;

return [{ json: { sqlQuery, queryParams } }];

const insertedRows = $input.all().map((item) => item.json);
return [{
  json: {
    success: true,
    inserted_count: insertedRows.length,
    inserted_ids: insertedRows.map((r) => r.id)
  }
}];

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
if (!token) throw new Error('Invalid or missing session token.');
return [{ json: { token, contacts: body.contacts || [] } }];

const r = $input.first().json;
if (!r.valid) throw new Error('Invalid session.');

const { contacts } = $('Extract Bearer Token ken & Rows').first().json;
return [{ json: { id: r.userId, role: r.role, name: r.user?.name, active: r.active, contacts } }];
